// Loading Screen
window.addEventListener('load', () => {
    const loader = document.getElementById('loadingScreen');
    const progress = document.querySelector('.loading-progress');
    if (progress) progress.style.width = '100%';
    setTimeout(() => {
        if (loader) loader.style.opacity = '0';
        setTimeout(() => { if (loader) loader.style.display = 'none'; }, 600);
    }, 1400);
});

// Custom Cursor
const dot = document.querySelector('.cursor-dot');
const ring = document.querySelector('.cursor-ring');
document.addEventListener('mousemove', (e) => {
    if (dot) dot.style.transform = `translate(${e.clientX - 2.5}px, ${e.clientY - 2.5}px)`;
    if (ring) ring.style.transform = `translate(${e.clientX - 18}px, ${e.clientY - 18}px)`;
});
// Refactored Cursor Hover Logic (Event Delegation for Modals/Dynamic Content)
window.addEventListener('mouseover', (e) => {
    const isClickable = e.target.closest('a, button, .feature-card-3d, .service-tilt, .portfolio-card, .close-modal, [role="button"]');
    if (ring) {
        if (isClickable) {
            ring.style.width = '52px';
            ring.style.height = '52px';
            ring.style.borderColor = 'rgba(0, 166, 255, 1)';
            ring.style.background = 'rgba(0, 166, 255, 0.05)';
        } else {
            ring.style.width = '36px';
            ring.style.height = '36px';
            ring.style.borderColor = 'rgba(0, 166, 255, 0.6)';
            ring.style.background = 'transparent';
        }
    }
});

// =====================================================
// PREMIUM MOBILE MENU — Animated Panel System
// =====================================================
const toggle = document.getElementById('mobileToggle');
const menu   = document.getElementById('navMenu');
let menuIsOpen = false;
let menuCloseTimer = null;

// Inject overlay backdrop (no HTML changes needed across pages)
const navOverlay = document.createElement('div');
navOverlay.className = 'nav-overlay';
document.body.appendChild(navOverlay);

function openMobileMenu() {
    if (menuIsOpen) return;
    menuIsOpen = true;
    if (menuCloseTimer) { clearTimeout(menuCloseTimer); menuCloseTimer = null; }
    menu.classList.remove('menu-closing');
    menu.classList.add('menu-open', 'active');
    if (toggle) {
        toggle.classList.add('nav-open');
        const icon = toggle.querySelector('i');
        if (icon) { icon.classList.remove('fa-bars'); icon.classList.add('fa-times'); }
    }
    navOverlay.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function closeMobileMenu() {
    if (!menuIsOpen) return;
    menuIsOpen = false;
    menu.classList.add('menu-closing');
    menu.classList.remove('menu-open', 'active');
    if (toggle) {
        toggle.classList.remove('nav-open');
        const icon = toggle.querySelector('i');
        if (icon) { icon.classList.remove('fa-times'); icon.classList.add('fa-bars'); }
    }
    navOverlay.classList.remove('active');
    document.body.style.overflow = '';
    menuCloseTimer = setTimeout(() => menu.classList.remove('menu-closing'), 300);
}

if (toggle) {
    toggle.addEventListener('click', (e) => {
        e.stopPropagation();
        menuIsOpen ? closeMobileMenu() : openMobileMenu();
    });
}
navOverlay.addEventListener('click', closeMobileMenu);
document.addEventListener('click', (e) => {
    if (menuIsOpen && !menu.contains(e.target) && !toggle?.contains(e.target)) closeMobileMenu();
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && menuIsOpen) closeMobileMenu(); });

// Navbar Click Animation + Active Link Handling
const navLinks = document.querySelectorAll('.nav-links a');

const setActiveNavLink = (activeLink) => {
    navLinks.forEach(link => link.classList.remove('active'));
    if (activeLink) activeLink.classList.add('active');
};

navLinks.forEach(link => {
    link.addEventListener('click', (e) => {
        link.classList.add('active');
        link.classList.add('nav-link-clicked');
        setTimeout(() => link.classList.remove('nav-link-clicked'), 220);
        if (menuIsOpen) closeMobileMenu();
    });
});

// Smooth Scroll for anchor links inside page
const pageAnchors = document.querySelectorAll('a[href^="#"]');
pageAnchors.forEach(anchor => {
    anchor.addEventListener('click', function(e) {
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
            e.preventDefault();
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            const matchingNav = document.querySelector(`.nav-links a[href="${this.getAttribute('href')}"]`);
            if (matchingNav) setActiveNavLink(matchingNav);
        }
    });
});

// Scroll spy for in-page sections
const sectionObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        const sectionId = entry.target.id;
        const matchingNav = document.querySelector(`.nav-links a[href="#${sectionId}"]`);
        if (matchingNav) {
            if (entry.isIntersecting) setActiveNavLink(matchingNav);
        }
    });
}, { threshold: 0.45 });

document.querySelectorAll('section[id]').forEach(section => sectionObserver.observe(section));

// Parallax Scroll Layers (data-speed)
window.addEventListener('scroll', () => {
    document.querySelectorAll('[data-speed]').forEach(el => {
        const speed = parseFloat(el.getAttribute('data-speed'));
        const yOffset = window.scrollY * speed;
        el.style.transform = `translateY(${yOffset}px)`;
    });
});

// 3D Tilt Effect on Hover (mousemove)
const tiltElements = document.querySelectorAll('[data-tilt]');
tiltElements.forEach(el => {
    el.addEventListener('mousemove', (e) => {
        const rect = el.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const rotateX = (y - centerY) / 15;
        const rotateY = (centerX - x) / 15;
        el.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`;
    });
    el.addEventListener('mouseleave', () => { el.style.transform = ''; });
});

// Scroll Reveal (fade-in, scale)
const revealItems = document.querySelectorAll('.feature-card-3d, .service-tilt, .timeline-card, .team-member, .portfolio-card, .service-card-3d');
const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });
}, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
revealItems.forEach(el => { el.classList.add('fade-in-scroll'); observer.observe(el); });

// Animated Counters (about page)
const counters = document.querySelectorAll('.stat-number');
if (counters.length) {
    const counterObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const el = entry.target;
                const target = parseInt(el.dataset.target);
                let curr = 0;
                const interval = setInterval(() => {
                    if (curr < target) { curr += Math.ceil(target / 45); el.innerText = curr; }
                    else { el.innerText = target; clearInterval(interval); }
                }, 30);
                counterObserver.unobserve(el);
            }
        });
    }, { threshold: 0.5 });
    counters.forEach(c => counterObserver.observe(c));
}

// Back to Top
const backBtn = document.getElementById('backToTop');
window.addEventListener('scroll', () => { 
    if (backBtn) {
        if (window.scrollY > 500) {
            backBtn.classList.add('visible');
        } else {
            backBtn.classList.remove('visible');
        }
    } 
});
if (backBtn) backBtn.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));

