// =====================================================
// HERO VIDEO — Robust Initialization
// =====================================================
//
// Common reasons a video source fails:
//   1. The URL is a webpage (e.g. pexels.com/video/123), not a direct .mp4 file.
//      Webpages return MIME type text/html — the <video> tag refuses to play them.
//   2. The CDN blocks cross-origin hotlinking (403 Forbidden).
//   3. CORS headers are missing, so the browser rejects the response.
//   4. The URL is a redirect — <video> doesn't reliably follow 301/302 redirects.
//
// SOLUTION: Always use a direct .mp4 URL.
//   Test it: paste the URL in a new browser tab — if it plays/downloads, it'll work here.
//   Pexels direct URL format: https://videos.pexels.com/video-files/XXXX/XXXX-hd...mp4
//
(function initHeroVideo() {
  const video = document.getElementById('heroVideo');
  if (!video) {
    console.warn('[HeroVideo] Element #heroVideo not found in DOM.');
    return;
  }

  // Force critical attributes — belt-and-suspenders for browsers that strip them
  video.muted    = true;        // Required for autoplay to work without user gesture
  video.loop     = true;
  video.playsInline = true;     // Prevents iOS from going fullscreen

  // ---- Fallback helper ----
  // Hides the broken video and shows a gradient background instead.
  function applyFallback(reason) {
    console.warn('[HeroVideo] Fallback activated. Reason:', reason);
    video.style.display = 'none';
    const container = document.querySelector('.hero-video-container');
    if (container) {
      // Gradient matches the site dark palette — hero still looks great
      container.style.background =
        'linear-gradient(135deg, #020408 0%, #060d1f 40%, #0a0e1a 70%, #020408 100%)';
    }
  }

  // ---- Source-level error (wrong URL, 403, CORS, MIME mismatch) ----
  const source = video.querySelector('source');
  if (source) {
    source.addEventListener('error', function () {
      console.error('[HeroVideo] <source> failed to load:', source.src);
      console.error('[HeroVideo] Verify the URL is a direct .mp4 file, not a webpage URL.');
      applyFallback('<source> load error');
    });
  }

  // ---- Video-element-level error ----
  video.addEventListener('error', function (e) {
    const err = video.error;
    const codes = {
      1: 'MEDIA_ERR_ABORTED — fetch was aborted',
      2: 'MEDIA_ERR_NETWORK — network error during load',
      3: 'MEDIA_ERR_DECODE — decoding failed (corrupt file?)',
      4: 'MEDIA_ERR_SRC_NOT_SUPPORTED — URL is not a playable video (wrong MIME type or blocked)',
    };
    const msg = err ? (codes[err.code] || 'Unknown error') : 'Unknown error';
    console.error('[HeroVideo] Video error:', msg, err);
    applyFallback(msg);
  });

  // ---- Attempt autoplay ----
  // Modern browsers return a Promise from .play().
  // Autoplay may be blocked if: not muted, no prior user interaction (mobile).
  const playPromise = video.play();
  if (playPromise !== undefined) {
    playPromise
      .then(function () {
        // Autoplay succeeded — all good
        console.log('[HeroVideo] Autoplay started successfully.');
      })
      .catch(function (err) {
        // Autoplay was blocked by browser policy (common on mobile)
        // The video is muted so this shouldn't happen often, but handle it anyway.
        console.warn('[HeroVideo] Autoplay blocked:', err.message);
        console.warn('[HeroVideo] Video will resume on first user interaction.');

        // Resume playback on first tap/click (silent, transparent to the user)
        function resumeOnInteraction() {
          video.play().catch(function () {});
          document.removeEventListener('click',      resumeOnInteraction);
          document.removeEventListener('touchstart', resumeOnInteraction);
          document.removeEventListener('keydown',    resumeOnInteraction);
        }
        document.addEventListener('click',      resumeOnInteraction, { once: true });
        document.addEventListener('touchstart', resumeOnInteraction, { once: true });
        document.addEventListener('keydown',    resumeOnInteraction, { once: true });
      });
  }
})();

